import { Button } from "@components/editor-ui/button";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@components/editor-ui/popover";
import { Separator } from "@components/editor-ui/separator";
import type { Editor } from "@tiptap/react";
import { useState, useCallback } from "react";

import { chainFocus } from "../lib/commands";
import { ColorSwatch } from "./color-swatch";
import { useEditorState, shallowEqual } from "./utils";

type SwatchType = "text" | "highlight";

interface RecentColor {
  type: SwatchType;
  color: string;
  label: string;
}

const RECENT_KEY = "editorcn-block-editor-recent-colors";
const RECENT_LIMIT = 10;

const ColorGroup = ({
  title,
  children,
  className,
}: {
  title: string;
  children: React.ReactNode;
  className: string;
}) => (
  <div className="block-editor-color-section">
    <span className="block-editor-color-label">{title}</span>
    <div className={className}>{children}</div>
  </div>
);

const storage = {
  get(): RecentColor[] {
    if (typeof window === "undefined") {
      return [];
    }
    try {
      const raw = window.localStorage.getItem(RECENT_KEY);
      if (!raw) {
        return [];
      }
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed.slice(0, RECENT_LIMIT) : [];
    } catch {
      return [];
    }
  },
  set(recent: RecentColor[]): void {
    try {
      window.localStorage.setItem(RECENT_KEY, JSON.stringify(recent));
    } catch {
      // Silently fail if localStorage is disabled or full
    }
  },
};

const TEXT_COLORS = [
  { color: "#0f172a", label: "Foreground" },
  { color: "#ef4444", label: "Red" },
  { color: "#f97316", label: "Orange" },
  { color: "#f59e0b", label: "Amber" },
  { color: "#22c55e", label: "Green" },
  { color: "#0ea5e9", label: "Sky" },
  { color: "#3b82f6", label: "Blue" },
  { color: "#6366f1", label: "Indigo" },
  { color: "#a855f7", label: "Purple" },
  { color: "#ec4899", label: "Pink" },
] as const;

const HIGHLIGHT_COLORS = [
  { color: "#fef08a", label: "Yellow" },
  { color: "#fed7aa", label: "Orange" },
  { color: "#fecaca", label: "Red" },
  { color: "#fbcfe8", label: "Pink" },
  { color: "#e9d5ff", label: "Purple" },
  { color: "#ddd6fe", label: "Violet" },
  { color: "#bfdbfe", label: "Blue" },
  { color: "#a5f3fc", label: "Cyan" },
  { color: "#99f6e4", label: "Teal" },
  { color: "#bbf7d0", label: "Green" },
] as const;

export const ColorSelector = ({ editor }: { editor: Editor }) => {
  const [open, setOpen] = useState(false);
  const [recent, setRecent] = useState<RecentColor[]>(storage.get);

  const { highlightColor, textColor } = useEditorState(
    editor,
    (ed) => ({
      highlightColor: ed.isActive("highlight")
        ? (ed.getAttributes("highlight").color as string | undefined)
        : undefined,
      textColor: ed.isActive("textStyle")
        ? (ed.getAttributes("textStyle").color as string | undefined)
        : undefined,
    }),
    shallowEqual
  );

  const hasColor = editor.extensionManager.extensions.some(
    (ext) => ext.name === "color"
  );
  const hasHighlight = editor.extensionManager.extensions.some(
    (ext) => ext.name === "highlight"
  );

  const rememberColor = useCallback(
    (type: SwatchType, color: string, label: string) => {
      setRecent((prev) => {
        const next = [
          { color, label, type },
          ...prev.filter(
            (item) => !(item.type === type && item.color === color)
          ),
        ].slice(0, RECENT_LIMIT);
        storage.set(next);
        return next;
      });
    },
    []
  );

  const selectColor = useCallback(
    (type: SwatchType, color: string, label: string) => {
      rememberColor(type, color, label);

      if (type === "text") {
        if (textColor === color) {
          chainFocus(editor).unsetColor().run();
        } else {
          chainFocus(editor).setColor(color).run();
        }
      } else if (highlightColor === color) {
        chainFocus(editor).unsetHighlight().run();
      } else {
        chainFocus(editor).setHighlight({ color }).run();
      }
    },
    [editor, textColor, highlightColor, rememberColor]
  );

  if (!hasColor && !hasHighlight) {
    return null;
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        render={
          <Button
            variant="ghost"
            size="icon-sm"
            data-active={Boolean(textColor || highlightColor) || undefined}
            aria-expanded={open}
            onMouseDown={(e) => e.preventDefault()}
            title="Text color"
            aria-label="Text color"
          />
        }
      >
        <span className="block-editor-color-icon">
          <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={2}
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M4 20h16" />
            <path d="m6 16 6-12 6 12" />
            <path d="M8 12h8" />
          </svg>
        </span>
      </PopoverTrigger>
      <PopoverContent className="p-2">
        {recent.length > 0 && (
          <ColorGroup
            title="Recently Used"
            className="block-editor-color-recent"
          >
            {recent.map((item) => (
              <ColorSwatch
                key={`${item.type}-${item.color}`}
                variant={item.type}
                color={item.color}
                label={item.label}
                active={
                  item.type === "text"
                    ? textColor === item.color
                    : highlightColor === item.color
                }
                onSelect={() => selectColor(item.type, item.color, item.label)}
              />
            ))}
          </ColorGroup>
        )}

        {hasColor && (
          <>
            {recent.length > 0 && <Separator className="my-2" />}
            <ColorGroup title="Text Color" className="block-editor-color-grid">
              {TEXT_COLORS.map((item) => (
                <ColorSwatch
                  key={item.color}
                  variant="text"
                  color={item.color}
                  label={item.label}
                  active={textColor === item.color}
                  onSelect={() => selectColor("text", item.color, item.label)}
                />
              ))}
            </ColorGroup>
          </>
        )}

        {hasHighlight && (
          <>
            {(recent.length > 0 || hasColor) && <Separator className="my-2" />}
            <ColorGroup
              title="Highlight Color"
              className="block-editor-color-grid"
            >
              {HIGHLIGHT_COLORS.map((item) => (
                <ColorSwatch
                  key={item.color}
                  variant="highlight"
                  color={item.color}
                  label={item.label}
                  active={highlightColor === item.color}
                  onSelect={() =>
                    selectColor("highlight", item.color, item.label)
                  }
                />
              ))}
            </ColorGroup>
          </>
        )}
      </PopoverContent>
    </Popover>
  );
};

import * as React from "react";

export interface ColorSwatchProps {
  color: string;
  label: string;
  variant: "text" | "highlight";
  active?: boolean;
  onSelect: (color: string) => void;
}

const getCheckColor = (hex: string): string => {
  const value = hex.replace("#", "");
  const r = Number.parseInt(value.slice(0, 2), 16) / 255;
  const g = Number.parseInt(value.slice(2, 4), 16) / 255;
  const b = Number.parseInt(value.slice(4, 6), 16) / 255;
  const luminance = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  return luminance > 0.5 ? "#18181b" : "#ffffff";
};

const ColorSwatch = React.forwardRef<HTMLButtonElement, ColorSwatchProps>(
  ({ color, label, variant, active = false, onSelect }, ref) => {
    const checkColor = getCheckColor(color);

    return (
      <button
        ref={ref}
        type="button"
        aria-pressed={active}
        aria-label={label}
        title={label}
        className={[
          "block-editor-color-swatch",
          variant === "text"
            ? "block-editor-color-swatch--text"
            : "block-editor-color-swatch--highlight",
          active ? "block-editor-color-swatch--active" : "",
        ]
          .filter(Boolean)
          .join(" ")}
        style={
          {
            "--swatch-check": checkColor,
            "--swatch-color": color,
          } as React.CSSProperties
        }
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => onSelect(color)}
      >
        {variant === "text" && !active ? (
          <span className="block-editor-color-glyph" aria-hidden="true">
            A
          </span>
        ) : null}
        {active ? (
          <span className="block-editor-color-check" aria-hidden="true">
            <svg
              xmlns="http://www.w3.org/2000/svg"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth={3}
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M20 6 9 17l-5-5" />
            </svg>
          </span>
        ) : null}
      </button>
    );
  }
);
ColorSwatch.displayName = "ColorSwatch";

export { ColorSwatch };

import type { Editor } from "@tiptap/core";
import { createContext, useContext } from "react";
