    transform 100ms ease-out,
    top 150ms ease-out,
    left 150ms ease-out;
  opacity: 0;
}

.drag-handle:hover {
  opacity: 1;
}

.drag-handle:active {
  cursor: grabbing;
  transform: scale(0.9);
}

.block-editor-content .ProseMirror:hover ~ .drag-handle,
